const input = $('Called by a workflow').first().json;
const row = input.row;
const q = input.config.alert_queue;
let payload = null;
let parseError = null;
try { payload = JSON.parse(row.payload); } catch (e) { parseError = e.message; }
// Other rows for the same Wazuh alert that are running or done (N8N-1.9).
// recv-wazuh-alert's lookup before the insert isn't atomic, so two copies can
// both be queued. A done copy: this row is a duplicate delivery and is
// finished without running the playbook. A running copy claimed before this
// row (earlier started_ms, then lower id): this row is given back and waits
// (no concurrent copies, A78). The claim time, not the id, decides, so a
// lower-id row requeued after a crash doesn't start next to a running copy.
const others = $('Same alert running or done').all().map((i) => i.json)
  .filter((r) => r.id !== undefined && r.id !== row.id);
const doneCopy = others.find((r) => r.status === 'done');
const before = (r) => Number(r.started_ms) < Number(row.started_ms)
  || (Number(r.started_ms) === Number(row.started_ms) && r.id < row.id);
const earlier = others.filter((r) => r.status === 'running' && before(r));
// Intake exclusions (lib-config), applied here since N8N-1.8: recv-wazuh-alert
// only filters on the level before it queues the raw alert.
const alert = payload !== null && typeof payload === 'object' ? payload.alert : undefined;
const rule = alert !== null && typeof alert === 'object' ? alert.rule : undefined;
const groups = rule !== null && typeof rule === 'object' && Array.isArray(rule.groups) ? rule.groups : [];
const ex = (input.config.intake_exclusions ?? []).find((e) => groups.includes(e.rule_group));
let action = 'run';
let reason = null;
if (doneCopy) {
  action = 'dedup';
  reason = `duplicate delivery: row ${doneCopy.id} for the same Wazuh alert is done (${doneCopy.outcome}); not run again (N8N-1.9)`;
} else if (earlier.length > 0) {
  action = 'yield';
  reason = `row ${earlier[0].id} for the same Wazuh alert is running (claimed first): given back to wait for it (no concurrent copies, A78)`;
} else if (parseError !== null) {
  action = 'fail';
  reason = `queued payload is not JSON (${parseError})`;
} else if (Number(row.attempts) > q.max_attempts) {
  action = 'fail';
  reason = `attempts exhausted (${q.max_attempts})`;
} else if (ex) {
  action = 'skip';
  reason = `skipped: ${ex.label}`;
}
return [{ json: { action, reason, payload, row_id: row.id, alert_id: row.alert_id, attempt: Number(row.attempts) } }];

// lib-route-alert failed (a broken routing table in lib-config): the row is
// marked failed and the alert parked with its id and payload (Row update),
// so it can be replayed once the table is fixed. Not retried: the same
// table gives the same failure.
const err = $input.first().json.error;
return [{ json: { route_error: true,
  message: 'routing failed: ' + (typeof err === 'string' ? err : err?.message ?? JSON.stringify($input.first().json).slice(0, 500)) } }];

// The route is recorded here (this execution is saved) and passed to the
// playbook with the alert and lib-config; the playbook puts it in TheHive
// (caseTemplate, writeback).
const input = $('Called by a workflow').first().json;
const d = $('Decide').first().json;
const route = $input.first().json.route;
return [{ json: {
  status: `routed: ${route.route_id} -> ${route.playbook}` + (route.fallback ? ` (fallback from ${route.fallback.wanted})` : ''),
  wazuh_alert_id: d.payload.wazuh_alert_id ?? null, route, alert: d.payload.alert,
  recv_execution_id: d.payload.recv_execution_id ?? null, config: input.config,
  queue: { row_id: d.row_id, attempt: d.attempt, slot: input.slot.name } } }];

// How the row ends: done, back to pending (retry), or failed (parked).
// The input item is the playbook's result, the routing error, or (no run)
// Decide's item.
const input = $('Called by a workflow').first().json;
const row = input.row;
const q = input.config.alert_queue;
const d = $('Decide').first().json;
const OK = ['created', 'duplicate', 'repaired', 'parked', 'skipped'];
let u;
let park = null;
let park_stage = null;
let outcome = 'none';
let route = null;
if (d.action === 'run') {
  const r = $input.first().json;
  if (r.route_error === true) {
    outcome = 'error';
    u = { status: 'failed', attempts: d.attempt, note: `attempt ${d.attempt}: ${r.message}`.slice(0, 600) + '; parked' };
    park = r.message;
    park_stage = 'route';
  } else {
    route = $('Playbook input').first().json.route;
    if (OK.includes(r.outcome)) {
      outcome = r.outcome;
      u = { status: 'done', attempts: d.attempt, note: `attempt ${d.attempt}: ${r.outcome}` + (r.thehive_alert_id ? `, TheHive ${r.thehive_alert_id}` : '') };
    } else {
      outcome = 'error';
      const e = r.error;
      const msg = `${typeof e === 'string' ? e : (e?.message ?? JSON.stringify(e ?? r))}`.slice(0, 500);
      if (d.attempt >= q.max_attempts) {
        u = { status: 'failed', attempts: d.attempt, note: `attempt ${d.attempt} of ${q.max_attempts} failed: ${msg}; parked` };
        park = msg;
        park_stage = 'queue';
      } else {
        u = { status: 'pending', attempts: d.attempt, note: `attempt ${d.attempt} failed: ${msg}; will retry` };
      }
    }
  }
} else if (d.action === 'yield') {
  u = { status: 'pending', attempts: d.attempt - 1, note: d.reason };
} else if (d.action === 'dedup') {
  outcome = 'duplicate_delivery';
  u = { status: 'done', attempts: d.attempt, note: `attempt ${d.attempt}: ${d.reason}` };
} else if (d.action === 'skip') {
  outcome = 'skipped';
  u = { status: 'done', attempts: d.attempt, note: `attempt ${d.attempt}: ${d.reason}` };
} else {
  outcome = 'error';
  u = { status: 'failed', attempts: d.attempt, note: `${d.reason}; parked` };
  park = d.reason;
  park_stage = 'queue';
}
return [{ json: { ...u, outcome, finished_ms: ['done', 'failed'].includes(u.status) ? Date.now() : 0, park, park_stage,
  route, playbook_id: route?.playbook_id ?? row.playbook_id ?? 'none' } }];

const input = $('Called by a workflow').first().json;
const u = $('Row update').first().json;
const d = $('Decide').first().json;
// A routing failure is parked as before N8N-1.8 (class unknown, stage route,
// the alert as payload); anything else as an exhausted queue row.
const routing = u.park_stage === 'route';
return [{ json: {
  error_class: routing ? 'unknown' : 'queue_attempts_exhausted',
  stage: routing ? 'route' : 'alert queue (lib-alert-queue-drain)', workflow: $workflow.name,
  execution_id: $execution.id, node: routing ? 'Route (lib-route-alert)' : 'Playbook (by route)', wazuh_alert_id: input.row.alert_id,
  thehive_alert_id: null, http_status: null, error_code: null, attempts: u.attempts,
  message: routing ? `alert ${input.row.alert_id} (queue row ${input.row.id}): ${u.park}` : `alert ${input.row.alert_id}: ${u.note}`,
  payload: routing ? (d.payload?.alert ?? null) : { queue_row: input.row.id } } }];

const input = $('Called by a workflow').first().json;
const u = $('Row update').first().json;
const finished = $('Finish row (compare-and-set)').first().json.id !== undefined;
const dp = input.depth;
const duration_ms = Date.now() - Number(input.row.started_ms);
const r = u.route;
const routed = r ? `; routed: ${r.route_id} -> ${r.playbook}` + (r.fallback ? ` (fallback from ${r.fallback.wanted})` : '') : '';
return [{ json: {
  status: `alert ${input.row.alert_id} (row ${input.row.id}, ${input.slot.name}): ${u.note}${routed}`
    + (finished ? '' : ' [row changed meanwhile: not updated]')
    + ` (${duration_ms} ms); row ${dp.run_row ?? 1} of this scheduler run; queue when the run started: ${dp.pending} pending, ${dp.running} running`,
  row_id: input.row.id, wazuh_alert_id: input.row.alert_id, row_status: u.status, outcome: u.outcome,
  route: r ? { route_id: r.route_id, playbook: r.playbook, matched_by: r.matched_by } : null,
  attempt: u.attempts, finished, duration_ms, depth: dp,
} }];
